fn main() {
    let v: Vec<u32> = (0..10).map(|x| x * 2).collect();
    println!("{:?}", v);
}

def fib(n):
	if n < 2:
		return n
	return fib(n - 1) + fib(n - 2)


print([fib(i) for i in range(20)])

